import{_ as t,o as n,c as o,ae as r}from"./chunks/framework.Dn7Y7LSn.js";const P=JSON.parse('{"title":"PHP এর ইতিহাস ও পরিচিতি (Live Class 1)","description":"","frontmatter":{},"headers":[],"relativePath":"module-1/introduction.md","filePath":"module-1/introduction.md"}'),s={name:"module-1/introduction.md"};function a(i,e,p,d,l,g){return n(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="php-এর-ইতিহাস-ও-পরিচিতি-live-class-1" tabindex="-1">PHP এর ইতিহাস ও পরিচিতি (Live Class 1) <a class="header-anchor" href="#php-এর-ইতিহাস-ও-পরিচিতি-live-class-1" aria-label="Permalink to &quot;PHP এর ইতিহাস ও পরিচিতি (Live Class 1)&quot;">​</a></h1><p>পিএইচপির ক্রিয়েটর <strong>Rasmus Lerdorf</strong>। ১৯৯৪ সালে পিএইচপির সূচনা হয় তাঁর হাতে। এর পূর্ণরূপ তখন ছিল <strong>Personal Home Page</strong>। শুরুর দিকে পিএইচপি ছিল C দিয়ে লেখা কিছু স্ক্রিপ্ট।</p><p>১৯৯৭ সালে <strong>Zeev Suraski</strong> ও <strong>Andi Gutmans</strong> নামের দুজন ডেভেলপার PHP পার্সারটিকে নতুন করে লেখেন। তখন এর পূর্ণরূপ হয়ে যায় <strong>Hypertext Preprocessor</strong>। এ সময়ের পিএইচপি ভার্সন ছিল PHP 3।</p><p>১৯৯৯ সালে Zeev ও Andi পিএইচপি পার্সারে আরও পরিবর্তন নিয়ে আসেন এবং এর নাম দেন <strong>Zend Engine</strong>। পিএইচপি কোড এই Zend Engine-এর মাধ্যমেই এক্সিকিউট হয়। এরপর আসে পিএইচপির নতুন ভার্সন PHP 4।</p><p>পিএইচপি ৫-এ অবজেক্ট ওরিয়েন্টেড প্রোগ্রামিং (OOP) সাপোর্ট চলে আসে। এরপর পিএইচপি ৬-এ ইউনিকোড সাপোর্ট নিয়ে আসার চেষ্টা করা হয়, কিন্তু এটি সফল না হওয়ায় পিএইচপি ৬ রিলিজ হয়নি।</p><p>এরপর আসে পিএইচপি ৭, যেখানে পারফরম্যান্স প্রায় দ্বিগুণ করা হয়। এর সাথে রিলিজ হয় <strong>Zend Engine 3</strong>। পিএইচপি ৭-এ টাইপ ম্যানেজমেন্ট এবং এরর হ্যান্ডলিং ইম্প্রুভ করা হয়।</p><p>২০২০ সালের নভেম্বরে আসে <strong>PHP 8</strong>, যেখানে <strong>JIT (Just-In-Time) Compiler</strong>, <strong>Attributes</strong>, <strong>Named Parameters</strong> সহ অনেক নতুন ফিচার নিয়ে আসা হয়। বর্তমানে পিএইচপি ফাউন্ডেশন তৈরি করা হয়েছে সবাইকে কানেক্টেড রাখার জন্য: <a href="https://opencollective.com/php-foundation" target="_blank" rel="noreferrer">opencollective.com/php-foundation</a></p><p>বর্তমানে পিএইচপির লেটেস্ট ভার্সন ৮.৩ এবং Zend Engine-এর ভার্সন ৪।</p>',8)])])}const m=t(s,[["render",a]]);export{P as __pageData,m as default};
